"""
Counting nucleotides which differ between two sequences.
Argument: two strings
Return: integer.
"""

def hamming_distance(s:str, t:str) -> int:
    if len(s) != len(t):
        return None
    d = 0
    for i in range(len(s)):
        if s[i] != t[i]:
            d += 1
    return d
        
def main() -> None:
    s = ""
    t = ""

    print(hamming_distance(s, t))


if __name__ == "__main__":
    main()